export function sceneFor(signal: Signal): string {
  return signal.mode === 'waiting' ? WAITING : WORKING
}

// What a screen reader hears for the scene.
export function altFor(signal: Signal): string {
  return signal.mode === 'waiting'
    ? "A fast fireworks finale in gold and white over the city: Claude needs you"
    : "Fireworks launching and bursting over a city skyline, confetti drifting down: Claude is working"
}
